def _logo_data_uri() -> str:
    global _LOGO_B64_CACHE
    if _LOGO_B64_CACHE:
        return _LOGO_B64_CACHE
    logo_path = _LOGO_PACKAGE
    if logo_path.exists():
        _LOGO_B64_CACHE = "data:image/png;base64," + base64.b64encode(logo_path.read_bytes()).decode()
    else:
        _LOGO_B64_CACHE = ""
    return _LOGO_B64_CACHE

_LOGO_HARDCODED = "data:image/png;base64,"

def _guide_domains(path: str | Path | None) -> set[str]:
    if not path or not Path(path).exists():
        return set()
    text = Path(path).read_text(encoding="utf-8", errors="replace")
    domains = set()
    for url in re.findall(r"https?://[^\s)\]>`]+", text):
        domain = (urlparse(url.rstrip(".,;'")).hostname or "").casefold().removeprefix("www.")
        if domain:
            domains.add(domain)
    return domains


def _topic(item: dict[str, Any]) -> str:
    desk = str(item.get("desk", "")).strip() or classify_editorial_desk(item)
    if desk:
        return desk
    text = " ".join(str(item.get(key, "")) for key in ("title", "subtitle", "summary", "source")).casefold()
    for topic, words in TOPIC_RULES.items():
        if any(word in text for word in words):
            return topic
    return "Actualidad general"


def is_requested_political_item(item: dict[str, Any]) -> bool:
    """Evita que el cable político mezcle deporte, clima o entretenimiento."""
    text = " ".join(str(item.get(key, "")) for key in ("title", "subtitle", "summary", "source")).casefold()
    return not any(term in text for term in NON_POLITICAL_TERMS) and any(term in text for term in POLITICAL_TERMS)


def _importance(item: dict[str, Any], guide_domains: set[str]) -> int:
    domain = (urlparse(str(item.get("url", ""))).hostname or "").casefold().removeprefix("www.")
    listed = any(domain == known or domain.endswith("." + known) for known in guide_domains)
    official = domain.endswith(".gob.ar") or domain in {"senado.gob.ar", "hcdn.gob.ar", "boletinoficial.gob.ar"}
    score = int(item.get("relevance_score", 0) or 0)
    score += 20 if official else 0
    score += 12 if listed else 0
    score += min(15, max(0, int(item.get("mentions", 1) or 1) - 1) * 5)
    return min(score, 100)


def _alert_level(item: dict[str, Any]) -> tuple[str, str, str, str]:
    """Nivel editorial visible en los productos HTML."""
    score = int(item.get("importance", item.get("relevance_score", 0)) or 0)
    if score >= 85:
        return "critica", "ALERTA CRÍTICA", "#C1432A", "#FDEEEA"
    if score >= 70:
        return "alta", "ALERTA ALTA", "#D99A1B", "#FFF6E2"
    return "seguimiento", "EN SEGUIMIENTO", "#1F8A4C", "#EAF7EF"


def _day_label(day_str: str) -> str:
    try:
        dt = datetime.strptime(day_str, "%Y-%m-%d")
        return f"{dt.day} de {_MONTH_ES[dt.month]} de {dt.year}"
    except (ValueError, KeyError):
        return day_str


def _logo_tag() -> str:
    uri = _logo_data_uri() or _LOGO_HARDCODED
    if uri:
        return f'<img class="logo" src="{uri}" alt="Consultora Diagonales">'
    return '<span class="logo-text">CONSULTORA DIAGONALES</span>'


def _cable_card(item: dict[str, Any]) -> str:
    importance = item.get("importance", item.get("relevance_score", 0))
    mentions = int(item.get("mentions", 1) or 1)
    level, level_label, _, _ = _alert_level(item)
    source = escape(str(item.get("source", "Fuente pública")))
    title = escape(str(item.get("title", "Sin título")))
    subtitle = escape(str(item.get("ai_summary") or item.get("subtitle") or item.get("summary") or "").strip()[:240])
    summary = escape(str(item.get("summary", "")))
    political_analysis = escape(str(item.get("political_analysis", "")))
    url = escape(str(item.get("url", "")), quote=True)
    topic = escape(str(item.get("topic", "Actualidad general")))
    mention_word = "menciones" if mentions != 1 else "mención"
    badge = (
        f"<div class='art-badge'>"
        f"<span class='art-mentions'>{mentions}</span>"
        f"<span class='art-mention-label'>{mention_word}</span>"
        f"</div>"
    )
    title_html = (
        f"<a href='{url}' target='_blank' rel='noopener noreferrer' class='title-link'>{title}</a>"
        if url else title
    )
    return (
        f"<article class='alert-{level}' data-mentions='{mentions}'>"
        f"<div class='art-head'>"
        + badge
        + f"<div class='art-body'>"
        f"<p class='tag'><span class='alert-level'>{level_label}</span> {topic} · IMPORTANCIA {importance}/100 · {source}</p>"
        f"<h2>{title_html}</h2>"
        + (f"<h3><b>Bajada:</b> {subtitle}</h3>" if subtitle else "")
        + (f"<p class='summary'>{summary}</p>" if summary and summary != subtitle else "")
        + (f"<p class='analysis'><b>Análisis político:</b> {political_analysis}</p>" if political_analysis else "")
        + f"<p class='meta'>relevancia {int(item.get('relevance_score', 0) or 0)}/100</p>"
        + (f"<p class='source-url'><b>URL:</b> <a href='{url}' target='_blank' rel='noopener noreferrer'>Abrir nota →</a></p>" if url else "")
        + "</div></div>"
        + "</article>"
    )


